WITH valid AS (SELECT *, ROUND(amount, 2) amount_rounded FROM payments WHERE status IN ('SUCCESS', 'FAILED')), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY amount_rounded, id) AS dedup_rank FROM valid QUALIFY dedup_rank = 1), with_windows AS (SELECT id, method, amount, paid_at, status, SUM(amount_rounded) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_amount_rounded, AVG(amount_rounded) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_amount_rounded, COUNT(amount_rounded) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_amount_rounded, AVG(amount) OVER (ORDER BY paid_at, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) amount_avg_5 FROM deduped), with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM with_windows), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), with_gaps_2 AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag_2 FROM islands), sessionized AS (SELECT *, SUM(new_group_flag_2) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps_2), with_gaps_3 AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessionized), sessionized_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id_2 FROM with_gaps_3) SELECT id, status, kpi, val FROM (SELECT id, status, running_avg_amount_rounded, running_sum_amount_rounded, amount FROM sessionized_payments) src UNPIVOT INCLUDE NULLS (val FOR kpi IN (running_avg_amount_rounded AS RUNNING_AVG_AMOUNT_ROUNDED, running_sum_amount_rounded AS RUNNING_SUM_AMOUNT_ROUNDED_VAL, amount AS AMOUNT));
